/**
 * What is this file?
 *
 * This file is a post-processing script for the OpenAPI specification.
 * It is run after the OpenAPI specification is generated by tsoa.
 * It injects the x-google-auth extension into the OpenAPI specification.
 *
 * Why do we need this file?
 *
 * TSOA does not support the x-google-auth extension.
 */
import fs from 'fs';
import yaml from 'js-yaml';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Paths relative to project root (frontend/api)
const openapiPath = path.resolve(__dirname, '../openapi.yaml');

try {
  const googleAuth = {
    issuer: 'https://accounts.google.com',
    jwksUri: 'https://www.googleapis.com/oauth2/v3/certs',
    audiences: ['${google_auth_client_id}'],
  };

  // Read openapi.yaml
  const openapiStr = fs.readFileSync(openapiPath, 'utf8');
  const openapi = yaml.load(openapiStr);

  // Inject
  if (openapi.components?.securitySchemes?.google_id_token) {
    openapi.components.securitySchemes.google_id_token['x-google-auth'] =
      googleAuth;

    // Write back
    fs.writeFileSync(
      openapiPath,
      yaml.dump(openapi, { noRefs: true, lineWidth: -1, quotingType: '"' })
    );
    console.log('Successfully injected x-google-auth into openapi.yaml');
  } else {
    console.error('Could not find google_id_token flows in openapi.yaml');
    process.exit(1);
  }
} catch (error) {
  console.error('Error during post-processing:', error);
  process.exit(1);
}
